package com.bank.data;

import java.math.BigDecimal;
import java.util.logging.*;

public class DataStoreDemo {
    private static final Logger log = Logger.getLogger("Data");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SqlLedger sql = new SqlLedger();
        sql.open("SAV2001", new BigDecimal("1000000"));
        sql.open("CUR3001", new BigDecimal("250000"));
        NoSqlActivityStore nosql = new NoSqlActivityStore();
        RedisCache cache = new RedisCache();
        BankDataService service = new BankDataService(sql, nosql, cache);

        // Cached balance read: first SQL miss, then cache hit
        log.info(() -> "balance1 " + service.getBalance("SAV2001"));
        log.info(() -> "balance2 " + service.getBalance("SAV2001"));

        // Transactional transfer in SQL + activity in NoSQL + cache invalidation
        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));

        // Balance after transfer reflects fresh SQL value
        log.info(() -> "balance after " + service.getBalance("SAV2001"));
        log.info(() -> "recent activity " + nosql.recent("SAV2001"));
    }
}

