// ─── File: SqlLedger.java ───
package com.bank.data;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

// Relational, ACID source of truth for balances.
public class SqlLedger {
    private static final Logger log = Logger.getLogger("Data");
    private final Map<String, BigDecimal> accounts = new HashMap<>();

    public void open(String id, BigDecimal opening) { accounts.put(id, opening); }
    public BigDecimal balance(String id) {
        log.fine(() -> "SQL read balance " + id);
        return accounts.get(id);
    }

    // simulate a single ACID transaction: both updates commit or neither
    public synchronized void transfer(String from, String to, BigDecimal amount) {
        BigDecimal fromBal = accounts.get(from);
        if (fromBal.compareTo(amount) < 0) throw new IllegalStateException("insufficient funds");
        accounts.put(from, fromBal.subtract(amount));
        accounts.put(to, accounts.get(to).add(amount));
        log.info(() -> "SQL committed transfer " + from + "->" + to + " Rs." + amount);
    }
}
```

