package com.bank.data;

import java.util.*;
import java.util.logging.*;

// Key-based, append-heavy, horizontally scalable activity log.
public class NoSqlActivityStore {
    private static final Logger log = Logger.getLogger("Data");
    private final Map<String, List<String>> byKey = new HashMap<>();

    public void append(String partitionKey, String event) {
        byKey.computeIfAbsent(partitionKey, k -> new ArrayList<>()).add(event);
        log.fine(() -> "NoSQL append " + partitionKey + " : " + event);
    }
    public List<String> recent(String partitionKey) {
        return byKey.getOrDefault(partitionKey, List.of());
    }
}
```

