package com.bank.data;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class RedisCache {
    private static final Logger log = Logger.getLogger("Data");
    private final Map<String, BigDecimal> cache = new HashMap<>();
    public BigDecimal get(String key) { return cache.get(key); }
    public void put(String key, BigDecimal v) { cache.put(key, v); }
    public void evict(String key) { cache.remove(key); log.fine(() -> "cache evict " + key); }
}
