// ─── File: BankDataService.java ───
package com.bank.data;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.logging.*;

public class BankDataService {
    private static final Logger log = Logger.getLogger("Data");
    private final SqlLedger sql;
    private final NoSqlActivityStore nosql;
    private final RedisCache cache;

    public BankDataService(SqlLedger sql, NoSqlActivityStore nosql, RedisCache cache) {
        this.sql = sql; this.nosql = nosql; this.cache = cache;
    }

    // cache-aside read: cache first, SQL on miss
    public BigDecimal getBalance(String id) {
        BigDecimal cached = cache.get(id);
        if (cached != null) { log.info(() -> "cache HIT balance " + id); return cached; }
        BigDecimal b = sql.balance(id);     // durable source of truth
        cache.put(id, b);
        log.info(() -> "cache MISS->SQL balance " + id);
        return b;
    }

    public void transfer(String from, String to, BigDecimal amount) {
        sql.transfer(from, to, amount);                         // SQL: strict ACID
        nosql.append(from, "TRANSFER out Rs." + amount + " @ " + Instant.now()); // NoSQL: scale
        nosql.append(to, "TRANSFER in Rs." + amount);
        cache.evict(from); cache.evict(to);                      // cache: keep fresh
    }
}
```
